        $bodies = [
            'about' => 'Аудандық білім порталы білім беру ұйымдары туралы ашық ақпаратты бір жерге жинайды. Мектептер каталогынан ұйымның мекенжайын, байланысын және ресми сайтының сілтемесін таба аласыз.\n\nЖаңалықтар, хабарландырулар және құжаттар бөлімдерінде білім бөлімі жариялаған материалдар көрсетіледі. Ақпаратты портал әкімшісі жаңартады.',
            'leadership' => 'Басшылық туралы ресми мәліметтер әзірге енгізілмеген. Әкімші осы бетке басшының аты-жөнін, лауазымын, қабылдау кестесін және қызметтік байланысын енгізе алады.',
            'structure' => 'Бөлім құрылымы туралы ресми мәліметтер әзірге енгізілмеген. Бұл бетте бөлімдердің атауы, міндеттері және қызметтік байланыстары жарияланады.',
            'teachers' => 'Педагогтер әдістемелік материалдарды тиісті бөлімнен таба алады. Құжаттар бөлімінде білім бөлімі жариялаған ресми материалдар орналасады. Жаңалықтар мен хабарландырулар арқылы семинарлар және өзге іс-шаралар туралы ақпаратпен танысыңыз.',
            'students' => 'Мектепті каталогтан тауып, оның ресми сайтына өтіңіз. Оқу материалдары үшін пайдалы сілтемелер бөлімін қараңыз. Байқаулар мен олимпиадалар туралы ақпарат жаңалықтар және хабарландырулар бөлімінде жарияланады.',
            'parents' => 'Мектептер каталогында ұйымның мекенжайы, телефоны және ресми сайты көрсетіледі. Қабылдау тәртібі туралы нақты ақпаратты мектептен немесе білім бөлімінен сұраңыз. Пайдалы сілтемелер арқылы электрондық күнделік пен мемлекеттік қызметтерге өте аласыз.',
            'admissions' => 'Мектепке қабылдау мерзімдері мен қажетті құжаттар туралы білім бөлімі жариялаған өзекті хабарландыруларды қараңыз. Нақты талаптарды мектептің ресми сайтынан немесе қызметтік байланысы арқылы нақтылаңыз. Бұл бетке ауданға қатысты бекітілген қабылдау ақпараты енгізіледі.',
            'anticorruption' => 'Бұл бетте білім бөлімінің сыбайлас жемқорлыққа қарсы іс-қимыл бойынша ресми материалдары, сенім байланыстары және өтініш беру тәртібі жарияланады. Қызметтік байланыстар Байланыс бөлімінде көрсетіледі. Жергілікті ресми мәліметтер әзірге енгізілмеген.',
        ];
        foreach (config('portal.pages') as $slug => $title) Page::firstOrCreate(['slug' => $slug], ['title' => $title, 'body' => str_replace('\\n', "\n", $bodies[$slug]), 'is_published' => true]);
