        foreach (['site_title' => 'Аудандық білім порталы', 'contact_address' => '', 'contact_phone' => '', 'contact_email' => '', 'office_hours' => '', 'contact_note' => 'Қызметтік байланыс мәліметтері әзірге енгізілмеген.'] as $key => $value) Setting::firstOrCreate(['key' => $key], ['value' => $value]);
